#[test]
fn invalid_hash160_inputs_are_rejected_not_silently_encoded() {
    let oracle_hash = [0xab_u8; 20];
    for bad in [
        "0x1234",                                     // wrong length
        "not-an-address",                             // neither hex nor base58check
        "0xzz0102030405060708090a0b0c0d0e0f10111213", // bad hex digits
    ] {
        assert!(
            create_invoke_script(
                &oracle_hash,
                "x",
                &[ContractParam::Hash160(bad.to_string())],
            )
            .is_err(),
            "expected rejection for {bad}"
        );
    }
    assert!(
        create_invoke_script(
            &oracle_hash,
            "x",
            &[ContractParam::HexBytes("abc".to_string())], // odd length
        )
        .is_err(),
        "expected rejection for odd-length HexBytes"
    );
}

#[test]
fn hash160_param_bytes_returns_wire_order() {
    // Wire order is the reversal of the big-endian input — that is exactly
    // what neon-js emitted for the asymmetric fixture (pinned above via the
    // full-script vector).
    let value = "0x0102030405060708090a0b0c0d0e0f1011121314";
    let wire = hash160_param_bytes(value).expect("valid 20-byte hex");
    assert_eq!(hex(&wire), "14131211100f0e0d0c0b0a090807060504030201");
    // Address form decodes to the same wire bytes: the first emitted arg in
    // the hash160_from_address vector (after PUSHDATA1 20) IS the wire form.
    let emitted = field("hash160_from_address_hex");
    let from_vector = &emitted[4..44];
    let from_address =
        hash160_param_bytes("NbrXdur6FV9bx33ME1jxjoKyQMBLZCWtDL").expect("valid address");
    assert_eq!(hex(&from_address), from_vector);
}
